import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import react from '@vitejs/plugin-react';
import { loadEnv, searchForWorkspaceRoot } from 'vite';
import { defineConfig } from 'vitest/config';
import { apiOriginOf, contentSecurityPolicy } from './csp';
import { parsePoseFilterSetting } from './src/filtering/poseFilterSetting';

const ROOT = fileURLToPath(new URL('.', import.meta.url));
// The app bundles @facefit/cv from source. Type checks read declarations
// generated by `npm run cv:types` instead, because the frontend's stricter
// compiler options would otherwise apply to the package's own files.
const CV_SOURCE = fileURLToPath(new URL('../packages/cv/src', import.meta.url));
// Same arrangement for @facefit/contracts: source for the bundle, declarations
// from `npm run contracts:build` for type checks. Its zod comes from the
// package's own node_modules, so the whole package directory is served.
const CONTRACTS = fileURLToPath(new URL('../packages/contracts', import.meta.url));

// Same fallback as src/services/apiClient.ts.
const DEFAULT_API_URL = 'http://localhost:5055';

// Part of the self-hosted asset path, so a version change also changes the URL.
const tasksVisionVersion = (
  JSON.parse(
    readFileSync(
      new URL('./node_modules/@mediapipe/tasks-vision/package.json', import.meta.url),
      'utf8',
    ),
  ) as { version: string }
).version;

export default defineConfig(({ command, mode }) => {
  const env = loadEnv(mode, ROOT, 'VITE_');
  // Throws on a value the app would not recognise, so the build fails.
  parsePoseFilterSetting(env.VITE_POSE_FILTER);
  const apiOrigin = apiOriginOf(env.VITE_API_URL || DEFAULT_API_URL);
  // A fresh nonce per dev server start; the production policy has none.
  const devNonce = randomBytes(16).toString('base64');

  return {
    plugins: [react()],
    resolve: {
      alias: {
        '@facefit/cv': `${CV_SOURCE}/index.ts`,
        '@facefit/contracts': `${CONTRACTS}/src/index.ts`,
      },
    },
    define: { __TASKS_VISION_VERSION__: JSON.stringify(tasksVisionVersion) },
    html: command === 'serve' ? { cspNonce: devNonce } : {},
    server: {
      port: 3000,
      fs: { allow: [searchForWorkspaceRoot(ROOT), CV_SOURCE, CONTRACTS] },
      headers: {
        'Content-Security-Policy': contentSecurityPolicy({ apiOrigin, nonce: devNonce }),
      },
    },
    preview: {
      headers: { 'Content-Security-Policy': contentSecurityPolicy({ apiOrigin }) },
    },
    build: { outDir: 'dist', sourcemap: false },
    test: {
      environment: 'jsdom',
      globals: true,
      setupFiles: ['./src/setupTests.ts'],
      css: false,
    },
  };
});
